    public async Task A_declined_response_is_read_back_as_declined()
    {
        var handler = new RecordingHandler(HttpStatusCode.OK, """{"status":"declined"}""");
        var sut = CreateSut(handler);

        var outcome = await sut.AuthorizeAsync("ORD-3", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
